// Fetch all metals-relevant sources in parallel.
const cfg = $('Config').first().json;
const runType = cfg.runType;
const tickers = cfg.tickers.split(',');
const windowMs = cfg.windowHours * 3600 * 1000;
const now = Date.now();
const since = now - windowMs;
const todayISO = new Date(now).toISOString().slice(0, 10);

const FINNHUB = $env.FINNHUB_API_KEY;
const FRED = $env.FRED_API_KEY;
const EIA = $env.EIA_API_KEY;
const MARKETAUX = $env.MARKETAUX_API_KEY;
const SEC_UA = 'metals-digest hunter547@gmail.com';

const CIK = {
  NEM: '0001164727', GOLD: '0000756894', AEM: '0000002809',
  WPM: '0001323404', FNV: '0001475880', AU: '0001067428',
  KGC: '0000701818', PAAS: '0000922475', HL: '0000719413',
  AG: '0001061768'
};

const MINER_NAMES = {
  NEM: 'Newmont', GOLD: 'Barrick Gold', AEM: 'Agnico Eagle',
  WPM: 'Wheaton Precious Metals', FNV: 'Franco-Nevada', AU: 'AngloGold Ashanti',
  KGC: 'Kinross Gold', PAAS: 'Pan American Silver', HL: 'Hecla Mining',
  AG: 'First Majestic Silver'
};

const helpers = this.helpers;
async function safeFetch(url, opts = {}) {
  try {
    return await helpers.httpRequest({ method: 'GET', url, headers: opts.headers || {}, json: true, timeout: 15000 });
  } catch (e) { return null; }
}

async function metalsComplex() {
  const SYMBOLS = [
    { sym: 'GC=F',  name: 'Gold (Comex)',           rank: 1 },
    { sym: 'SI=F',  name: 'Silver (Comex)',         rank: 2 },
    { sym: 'HG=F',  name: 'Copper (Comex)',         rank: 3 },
    { sym: 'GLD',   name: 'SPDR Gold Shares',       rank: 4 },
    { sym: 'SLV',   name: 'iShares Silver Trust',   rank: 5 },
    { sym: 'GDX',   name: 'VanEck Gold Miners',     rank: 6 },
    { sym: 'GDXJ',  name: 'VanEck Jr Gold Miners',  rank: 7 },
    { sym: 'SIL',   name: 'Global X Silver Miners', rank: 8 }
  ];
  const out = [];
  await Promise.all(SYMBOLS.map(async (t) => {
    const j = await safeFetch(`https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(t.sym)}?range=2d&interval=1d`, { headers: { 'User-Agent': 'Mozilla/5.0' } });
    const r = j?.chart?.result?.[0];
    if (!r) return;
    const meta = r.meta || {};
    const last = meta.regularMarketPrice;
    const prev = meta.chartPreviousClose ?? meta.previousClose;
    if (last == null) return;
    const pct = (prev && prev !== 0) ? ((last - prev) / prev * 100) : null;
    out.push({
      source: 'yahoo_metals',
      external_id: `metals_${t.sym}_${todayISO}_${runType}`,
      category: 'metals_complex',
      ticker: t.sym,
      title: `${t.name} (${t.sym}): ${Number(last).toFixed(2)}${pct !== null ? ` (${pct.toFixed(2)}%)` : ''}`,
      body: `Prev close ${prev != null ? Number(prev).toFixed(2) : 'n/a'}.`,
      ts: new Date((meta.regularMarketTime || Math.floor(Date.now()/1000)) * 1000).toISOString(),
      url: `https://finance.yahoo.com/quote/${encodeURIComponent(t.sym)}`,
      rank: t.rank, name: t.name, price: last, prevClose: prev, pct
    });
  }));
  const gold = out.find(i => i.ticker === 'GC=F');
  const silver = out.find(i => i.ticker === 'SI=F');
  if (gold && silver && silver.price) {
    const ratio = gold.price / silver.price;
    out.push({
      source: 'derived', external_id: `gsr_${todayISO}_${runType}`,
      category: 'metals_complex', ticker: 'GSR', name: 'Gold/Silver Ratio',
      title: `Gold/Silver Ratio: ${ratio.toFixed(2)}`,
      body: `GC=F ${gold.price.toFixed(2)} \u00f7 SI=F ${silver.price.toFixed(2)}.`,
      ts: new Date().toISOString(), url: '',
      rank: 99, price: ratio, prevClose: null, pct: null
    });
  }
  return out.sort((a, b) => a.rank - b.rank);
}

async function realYields() {
  if (!FRED) return [];
  const series = [
    { id: 'DFII10', label: '10Y TIPS yield (real)' },
    { id: 'DFII5',  label: '5Y TIPS yield (real)' },
    { id: 'DFII2',  label: '2Y TIPS yield (real)' },
    { id: 'DGS10',  label: '10Y Treasury yield (nominal)' },
    { id: 'DGS2',   label: '2Y Treasury yield (nominal)' },
    { id: 'T10YIE', label: '10Y breakeven inflation' },
    { id: 'T5YIE',  label: '5Y breakeven inflation' },
    { id: 'T5YIFR', label: '5Y/5Y forward inflation' }
  ];
  const out = [];
  for (const s of series) {
    const j = await safeFetch(`https://api.stlouisfed.org/fred/series/observations?series_id=${s.id}&api_key=${FRED}&file_type=json&sort_order=desc&limit=2`);
    if (!j?.observations?.length) continue;
    const o = j.observations[0]; const prev = j.observations[1];
    out.push({
      source: 'fred_yields', external_id: `${s.id}_${o.date}`, category: 'real_yields', ticker: null,
      title: `${s.label} (${s.id}): ${o.value}% (as of ${o.date})`,
      body: prev ? `Prev ${prev.value}% on ${prev.date}` : '',
      ts: o.date, url: `https://fred.stlouisfed.org/series/${s.id}`
    });
  }
  return out;
}

