async function minerQuotes() {
  const out = [];
  await Promise.all(tickers.map(async (sym, idx) => {
    const j = await safeFetch(`https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(sym)}?range=2d&interval=1d`, { headers: { 'User-Agent': 'Mozilla/5.0' } });
    const r = j?.chart?.result?.[0];
    if (!r) return;
    const meta = r.meta || {};
    const last = meta.regularMarketPrice;
    const prev = meta.chartPreviousClose ?? meta.previousClose;
    if (last == null) return;
    const pct = (prev && prev !== 0) ? ((last - prev) / prev * 100) : null;
    const name = MINER_NAMES[sym] || sym;
    out.push({
      source: 'yahoo_miners', external_id: `miner_${sym}_${todayISO}_${runType}`,
      category: 'mining_equity', ticker: sym,
      title: `${sym} ${name}: $${Number(last).toFixed(2)}${pct !== null ? ` (${pct.toFixed(2)}%)` : ''}`,
      body: `Prev close $${prev != null ? Number(prev).toFixed(2) : 'n/a'}.`,
      ts: new Date((meta.regularMarketTime || Math.floor(Date.now()/1000)) * 1000).toISOString(),
      url: `https://finance.yahoo.com/quote/${encodeURIComponent(sym)}`,
      rank: idx + 1, name, price: last, prevClose: prev, pct
    });
  }));
  return out.sort((a, b) => a.rank - b.rank);
}

async function minerNews() {
  if (!FINNHUB) return [];
  const fromISO = new Date(now - 2 * 86400000).toISOString().slice(0, 10);
  const toISO = new Date(now).toISOString().slice(0, 10);
  const out = [];
  await Promise.all(tickers.map(async (sym) => {
    const j = await safeFetch(`https://finnhub.io/api/v1/company-news?symbol=${sym}&from=${fromISO}&to=${toISO}&token=${FINNHUB}`);
    if (!Array.isArray(j)) return;
    for (const n of j.slice(0, 2)) {
      if (!n.headline) continue;
      out.push({
        source: 'finnhub_company_news', external_id: `${sym}_${n.id}`,
        category: 'news', ticker: sym, title: n.headline,
        body: (n.summary || '').slice(0, 280),
        ts: new Date(n.datetime * 1000).toISOString(), url: n.url
      });
    }
  }));
  return out;
}

async function earningsCal() {
  if (!FINNHUB) return [];
  const fromISO = new Date(now - 86400000).toISOString().slice(0, 10);
  const toISO = new Date(now + 7 * 86400000).toISOString().slice(0, 10);
  const j = await safeFetch(`https://finnhub.io/api/v1/calendar/earnings?from=${fromISO}&to=${toISO}&token=${FINNHUB}`);
  if (!j?.earningsCalendar) return [];
  return j.earningsCalendar.filter(e => tickers.includes(e.symbol)).map(e => ({
    source: 'finnhub_earnings',
    external_id: `${e.symbol}_${e.date}_${e.hour}`,
    category: 'earnings', ticker: e.symbol,
    title: `${e.symbol} earnings ${e.hour === 'bmo' ? 'pre-market' : e.hour === 'amc' ? 'after-close' : e.date}`,
    body: `EPS est ${e.epsEstimate ?? 'n/a'}, rev est ${e.revenueEstimate ?? 'n/a'}. Actual EPS ${e.epsActual ?? 'pending'}, actual rev ${e.revenueActual ?? 'pending'}.`,
    ts: e.date, url: `https://finance.yahoo.com/quote/${e.symbol}`
  }));
}

async function edgarFilings() {
  const out = [];
  for (const [ticker, cik] of Object.entries(CIK)) {
    if (!tickers.includes(ticker)) continue;
    const j = await safeFetch(`https://data.sec.gov/submissions/CIK${cik}.json`, { headers: { 'User-Agent': SEC_UA, 'Accept': 'application/json' } });
    if (!j?.filings?.recent) continue;
    const r = j.filings.recent;
    const edgarSince = now - 5 * 86400000;
    for (let i = 0; i < r.form.length && i < 30; i++) {
      if (!['8-K','6-K','20-F','40-F'].includes(r.form[i])) continue;
      const filedAt = new Date(r.filingDate[i]).getTime();
      if (filedAt < edgarSince) continue;
      const accNo = r.accessionNumber[i].replace(/-/g, '');
      out.push({
        source: 'sec_edgar', external_id: r.accessionNumber[i], category: 'earnings', ticker,
        title: `${ticker} ${r.form[i]} filed ${r.filingDate[i]}`,
        body: r.primaryDocDescription[i] || `${r.form[i]} filing`,
        ts: r.filingDate[i],
        url: `https://www.sec.gov/Archives/edgar/data/${parseInt(cik)}/${accNo}/${r.primaryDocument[i]}`
      });
    }
  }
  return out;
}

