async function treasuryAuctions() {
  const j = await safeFetch('https://www.treasurydirect.gov/TA_WS/securities/announced?format=json');
  if (!Array.isArray(j)) return [];
  return j.slice(0, 10).map(a => {
    const isTips = (a.securityType || '').toUpperCase().includes('TIPS') || (a.securityTerm || '').toUpperCase().includes('TIPS');
    return {
      source: 'treasury', external_id: a.cusip, category: 'macro', ticker: null,
      title: `Treasury auction: ${a.securityType} ${a.securityTerm} on ${a.auctionDate}${isTips ? ' [TIPS]' : ''}`,
      body: `Issue ${a.issueDate}, offering ${a.offeringAmount || 'TBA'}.`,
      ts: a.auctionDate, url: 'https://www.treasurydirect.gov/auctions/upcoming/'
    };
  });
}

async function eiaPetroleum() {
  if (!EIA) return [];
  const url = `https://api.eia.gov/v2/petroleum/stoc/wstk/data/?api_key=${EIA}&frequency=weekly&data[0]=value&facets[duoarea][]=NUS&sort[0][column]=period&sort[0][direction]=desc&length=200`;
  const j = await safeFetch(url);
  const rows = j?.response?.data;
  if (!rows?.length) return [];
  const KEY = /^U\.S\. Ending Stocks of (Crude Oil( and Lease Condensate)?|(Total )?(Motor )?Gasoline|Distillate Fuel Oil)$/i;
  const seen = new Set();
  return rows
    .filter(r => KEY.test(r['series-description']))
    .filter(r => { const k = r['series-description']; if (seen.has(k)) return false; seen.add(k); return true; })
    .slice(0, 4)
    .map(r => ({
      source: 'eia', external_id: `${r['series-description']}_${r.period}`, category: 'cross_asset', ticker: null,
      title: `EIA: ${r['series-description']} ${r.period}`,
      body: `${r.value} ${r.units}`,
      ts: r.period, url: 'https://www.eia.gov/petroleum/supply/weekly/'
    }));
}

const NEWS_RELEVANT = /\b(gold|silver|copper|precious metal|bullion|comex|lbma|gld|slv|gdx|gdxj|miner(s)?|newmont|barrick|agnico|wheaton|franco-nevada|kinross|pan american|hecla|fed|fomc|powell|rate (cut|hike|decision)|interest rate|real yield|tips|breakeven|inflation|cpi|pce|ppi|jobs report|payroll|nonfarm|unemployment|gdp|treasury yield|10-year|yield curve|dollar index|dxy|de-?dollarization|safe[- ]haven|geopolitic|israel|iran|russia|ukraine|china (trade|export|reserves)|sanction|tariff|recession|hawkish|dovish|fed minutes|jackson hole|debt ceiling|government shutdown|central bank (gold|reserves|buy)|pboc|rbi|imf)\b/i;
async function finnhubNews() {
  if (!FINNHUB) return [];
  const j = await safeFetch(`https://finnhub.io/api/v1/news?category=general&token=${FINNHUB}`);
  if (!Array.isArray(j)) return [];
  return j
    .filter(n => n.datetime * 1000 >= since)
    .filter(n => NEWS_RELEVANT.test((n.headline || '') + ' ' + (n.summary || '')))
    .slice(0, 20)
    .map(n => ({
      source: 'finnhub_news', external_id: String(n.id), category: 'news', ticker: null,
      title: n.headline, body: n.summary || '',
      ts: new Date(n.datetime * 1000).toISOString(), url: n.url
    }));
}

async function marketauxNews() {
  if (!MARKETAUX) return [];
  const url = `https://api.marketaux.com/v1/news/all?countries=us,gb,ca,au&language=en&search=gold+OR+silver+OR+precious+OR+bullion+OR+miner+OR+inflation+OR+fed+OR+yields&published_after=${new Date(since).toISOString()}&api_token=${MARKETAUX}&limit=20`;
  const j = await safeFetch(url);
  if (!j?.data) return [];
  return j.data.map(n => ({
    source: 'marketaux', external_id: n.uuid, category: 'news',
    ticker: (n.entities || []).map(e => e.symbol).filter(Boolean).join(',') || null,
    title: n.title, body: n.description || '',
    ts: n.published_at, url: n.url
  }));
}

async function forexFactory() {
  const urls = ['https://nfs.faireconomy.media/ff_calendar_thisweek.json', 'https://nfs.faireconomy.media/ff_calendar_nextweek.json'];
  const results = await Promise.all(urls.map(u => safeFetch(u)));
  const events = results.flatMap(r => Array.isArray(r) ? r : []);
  if (!events.length) return [];
  const cutoff = now + 5 * 86400000;
  return events
    .filter(e => e.country === 'USD' && (e.impact === 'High' || e.impact === 'Medium'))
    .filter(e => { const t = new Date(e.date).getTime(); return !isNaN(t) && t >= now && t <= cutoff; })
    .map(e => ({
      source: 'forexfactory',
      external_id: `ff_${e.title}_${e.date}`,
      category: 'econ_calendar', ticker: null,
      title: e.title,
      body: `Impact: ${e.impact} | Forecast: ${e.forecast || 'n/a'} | Prev: ${e.previous || 'n/a'}`,
      ts: e.date, url: 'https://www.forexfactory.com/calendar',
      impact: e.impact, forecast: e.forecast || null, previous: e.previous || null,
      eventDate: e.date
    }));
}

async function cftcCot() {
  // CFTC Disaggregated Futures-Only Reports (public Socrata, no key required).
  const url = "https://publicreporting.cftc.gov/resource/72hh-3qpy.json?$where=commodity_subgroup_name='PRECIOUS METALS' AND (contract_market_name='GOLD' OR contract_market_name='SILVER')&$order=report_date_as_yyyy_mm_dd DESC&$limit=20";
  const j = await safeFetch(url);
  if (!Array.isArray(j) || !j.length) return [];
  const byContract = {};
  for (const r of j) {
    const c = r.contract_market_name;
    if (!byContract[c]) byContract[c] = [];
    if (byContract[c].length < 2) byContract[c].push(r);
  }
  const out = [];
  for (const [contract, rows] of Object.entries(byContract)) {
    const cur = rows[0]; const prev = rows[1];
    if (!cur) continue;
    const long = Number(cur.m_money_positions_long_all) || 0;
    const short = Number(cur.m_money_positions_short_all) || 0;
    const mmNet = long - short;
    const mmNetPrev = prev ? ((Number(prev.m_money_positions_long_all) || 0) - (Number(prev.m_money_positions_short_all) || 0)) : null;
    const wow = mmNetPrev != null ? mmNet - mmNetPrev : null;
    out.push({
      source: 'cftc_cot',
      external_id: `cot_${contract}_${cur.report_date_as_yyyy_mm_dd}`,
      category: 'positioning', ticker: contract === 'GOLD' ? 'GC=F' : 'SI=F',
      title: `CFTC COT ${contract}: managed-money net ${mmNet.toLocaleString()} contracts (${cur.report_date_as_yyyy_mm_dd})`,
      body: wow != null ? `Week-over-week change ${wow >= 0 ? '+' : ''}${wow.toLocaleString()} contracts. Long ${long.toLocaleString()} / Short ${short.toLocaleString()}.` : `Long ${long.toLocaleString()} / Short ${short.toLocaleString()}.`,
      ts: cur.report_date_as_yyyy_mm_dd,
      url: 'https://www.cftc.gov/MarketReports/CommitmentsofTraders/'
    });
  }
  return out;
}

const results = await Promise.allSettled([
  metalsComplex(), realYields(), dollarFx(), riskContext(),
  minerQuotes(), minerNews(), earningsCal(), edgarFilings(),
  fredReleases(), treasuryAuctions(), eiaPetroleum(),
  finnhubNews(), marketauxNews(), forexFactory(), cftcCot()
]);
const items = results.flatMap(r => r.status === 'fulfilled' ? r.value : []);
return items.map(json => ({ json }));

const items = $('Fetch All Sources').all().map(i => i.json);
const seen = new Set($('Load Seen IDs').all().map(i => i.json.external_id));
const fresh = items.filter(it => !seen.has(it.external_id));
return fresh.map(json => ({ json }));

// Build user prompt asking Claude for STRUCTURED JSON for precious metals.
const items = $('Fetch All Sources').all().map(i => i.json);
const runType = $('Config').first().json.runType;

const bucket = (cat) => items.filter(i => i.category === cat).slice(0, 30);
const earnings = bucket('earnings');
const macro = bucket('macro');
const realYieldsB = bucket('real_yields');
const fxB = bucket('dollar_fx');
const news = bucket('news');
const cross = bucket('cross_asset');
const positioning = bucket('positioning');
const metals = items.filter(i => i.category === 'metals_complex').sort((a, b) => a.rank - b.rank);
const miners = items.filter(i => i.category === 'mining_equity').sort((a, b) => a.rank - b.rank);
const econCal = items.filter(i => i.category === 'econ_calendar').slice().sort((a, b) => new Date(a.eventDate) - new Date(b.eventDate));

const fmt = (arr) => arr.length
  ? arr.map(i => `- [${i.source}${i.ticker ? ' ' + i.ticker : ''}] ${i.title}${i.body ? ' \u2014 ' + i.body.slice(0, 280) : ''}`).join('\n')
  : '(none)';

const fmtEcon = (arr) => arr.length
  ? arr.map(e => {
      const t = new Date(e.eventDate);
      const dStr = t.toLocaleDateString('en-US', { timeZone: 'America/New_York', weekday: 'short', month: 'short', day: 'numeric' });
      const tStr = t.toLocaleTimeString('en-US', { timeZone: 'America/New_York', hour: '2-digit', minute: '2-digit', hour12: false });
