const cleaned = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '').trim();
let parsed = tryParse(cleaned);
if (!parsed) {
  const m = cleaned.match(/\{[\s\S]*\}/);
  parsed = m ? tryParse(m[0]) : null;
}
if (!parsed || typeof parsed !== 'object') parsed = { metals: [], real_yields: [], dollar_fx: [], macro: [], miners: [], positioning: [], news: [], bias_read: '' };
for (const k of ['metals','real_yields','dollar_fx','macro','miners','positioning','news']) if (!Array.isArray(parsed[k])) parsed[k] = [];

let bias = typeof parsed.bias_read === 'string' ? parsed.bias_read.trim() : '';
if (bias.startsWith('{') || /"bias_read"\s*:/.test(bias)) {
  const inner = bias.match(/"bias_read"\s*:\s*"((?:[^"\\]|\\.)*)"/);
  try { bias = inner ? JSON.parse('"' + inner[1] + '"') : ''; } catch (e) { bias = ''; }
}
bias = bias.replace(/\s+/g, ' ').slice(0, 600);
parsed.bias_read = bias || '(model returned no bias)';

const runType = $('Build Prompt').first().json.runType;
const itemCount = $('Build Prompt').first().json.itemCount;
const items = $('Fetch All Sources').all().map(i => i.json);
return [{ json: { ...parsed, runType, itemCount, items } }];

